import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import java.io.File;
import java.sql.*;
import java.util.*;
import java.util.List;

public class Cinemax {
    static final Color BG=new Color(10,12,24), PANEL=new Color(20,24,43), PANEL2=new Color(29,34,58);
    static final Color PINK=new Color(255,55,125), PURPLE=new Color(143,82,255), CYAN=new Color(43,220,235);
    static final Color TEXT=new Color(245,246,255), MUTED=new Color(173,180,205), GREEN=new Color(65,220,155);
    static Connection connection;
    static JFrame frame;
    static String currentUser="guest";
    static boolean admin=false;
    static JPanel main;
    static final String DB="data/cinemax.db";
    static class Movie { int id; String title, language, genre, poster; double price; Movie(int i,String t,String l,String g,double p,String po){id=i;title=t;language=l;genre=g;price=p;poster=po;} }
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try { UIManager.setLookAndFeel(UIManager.getCrossPlatformLookAndFeelClassName()); }
            catch(Exception ignored){}
            try { initDb(); showLogin(); }
            catch(Exception e){ error("Could not start database: "+e.getMessage()); }
        });
    }
    static Connection db() throws SQLException {
        Connection c=DriverManager.getConnection("jdbc:sqlite:"+new File(DB).getAbsolutePath());
        try(Statement s=c.createStatement()){s.execute("PRAGMA busy_timeout=8000");}
        return c;
    }
    static void initDb() throws SQLException {
        new File("data").mkdirs();
        try(Connection c=db(); Statement s=c.createStatement()){
            s.execute("PRAGMA journal_mode=WAL");
            s.execute("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, password TEXT, role TEXT DEFAULT 'USER')");
            s.execute("CREATE TABLE IF NOT EXISTS movies(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,language TEXT,genre TEXT,price REAL,poster TEXT)");
            s.execute("CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT,movie_id INTEGER,movie_title TEXT,show_time TEXT,seats TEXT,total REAL,status TEXT DEFAULT 'BOOKED',created_at TEXT DEFAULT CURRENT_TIMESTAMP)");
            try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO users(username,password,role) VALUES(?,?,?)")){p.setString(1,"admin");p.setString(2,"admin123");p.setString(3,"ADMIN");p.executeUpdate();}
            try(ResultSet r=s.executeQuery("SELECT COUNT(*) FROM movies")){if(r.next()&&r.getInt(1)==0){
                String[][] m={{"Leo","Tamil","Action","180","posters/leo.jpg"},{"Jailer","Tamil","Action","170","posters/jailer.jpg"},{"Master","Tamil","Action","160","posters/master.jpg"},{"Lucifer","Malayalam","Thriller","150","posters/lucifer.jpg"},{"Drishyam","Malayalam","Thriller","140","posters/drishyam.jpg"},{"Premalu","Malayalam","Romance","150","posters/premalu.jpg"},{"Aavesham","Malayalam","Comedy","170","posters/aavesham.jpg"},{"Manjummel Boys","Malayalam","Drama","160","posters/manjummel_boys.jpg"},{"Vikram","Tamil","Action","180","posters/vikram.jpg"},{"Baahubali","Telugu","Epic","190","posters/baahubali.jpg"},{"Sita Ramam","Telugu","Romance","160","posters/sita_ramam.jpg"},{"Interstellar","English","Sci-Fi","220","posters/interstellar.jpg"}};
                try(PreparedStatement p=c.prepareStatement("INSERT INTO movies(title,language,genre,price,poster) VALUES(?,?,?,?,?)")){for(String[] a:m){p.setString(1,a[0]);p.setString(2,a[1]);p.setString(3,a[2]);p.setDouble(4,Double.parseDouble(a[3]));p.setString(5,a[4]);p.addBatch();}p.executeBatch();}
            }}
        }
    }
    static void styleButton(JButton b, Color color){b.setFont(new Font("Segoe UI",Font.BOLD,14));b.setForeground(Color.WHITE);b.setBackground(color);b.setOpaque(true);b.setContentAreaFilled(true);b.setBorderPainted(false);b.setFocusPainted(false);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.setBorder(new EmptyBorder(10,16,10,16));}
    static JButton button(String label,Color color,Runnable action){JButton b=new JButton(label);styleButton(b,color);b.addActionListener(e->action.run());return b;}
    static JLabel label(String s,int size,Color color){JLabel l=new JLabel(s);l.setFont(new Font("Segoe UI",Font.BOLD,size));l.setForeground(color);return l;}
    static JTextField field(String hint){JTextField f=new JTextField();f.setFont(new Font("Segoe UI",Font.PLAIN,15));f.setForeground(TEXT);f.setCaretColor(CYAN);f.setBackground(PANEL2);f.setBorder(new CompoundBorder(new LineBorder(new Color(68,76,115)),new EmptyBorder(10,12,10,12)));f.setToolTipText(hint);return f;}
    static JPasswordField password(){JPasswordField f=new JPasswordField();f.setFont(new Font("Segoe UI",Font.PLAIN,15));f.setForeground(TEXT);f.setCaretColor(CYAN);f.setBackground(PANEL2);f.setBorder(new CompoundBorder(new LineBorder(new Color(68,76,115)),new EmptyBorder(10,12,10,12)));return f;}
    static void base(String title){frame=new JFrame(title);frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);frame.setSize(1180,780);frame.setMinimumSize(new Dimension(900,650));frame.setLocationRelativeTo(null);frame.getContentPane().setBackground(BG);}
    static void showLogin(){
        base("CINEMAX | Your Movie Universe"); JPanel outer=new JPanel(new GridBagLayout());outer.setBackground(BG);
        JPanel card=new JPanel();card.setBackground(PANEL);card.setBorder(new CompoundBorder(new LineBorder(new Color(67,49,115),1),new EmptyBorder(32,38,32,38)));card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.setPreferredSize(new Dimension(430,510));
        JLabel brand=label("CINEMAX",34,PINK);brand.setAlignmentX(Component.CENTER_ALIGNMENT); JLabel tagline=label("YOUR SEAT. YOUR SHOW. YOUR CINEMA.",12,CYAN);tagline.setAlignmentX(Component.CENTER_ALIGNMENT);
        JTextField user=field("Username");JPasswordField pass=password();user.setMaximumSize(new Dimension(360,44));pass.setMaximumSize(new Dimension(360,44));
        card.add(brand);card.add(Box.createVerticalStrut(8));card.add(tagline);card.add(Box.createVerticalStrut(30));card.add(label("Welcome to the big screen",21,TEXT));card.add(Box.createVerticalStrut(18));card.add(label("USERNAME",11,MUTED));card.add(Box.createVerticalStrut(5));card.add(user);card.add(Box.createVerticalStrut(14));card.add(label("PASSWORD",11,MUTED));card.add(Box.createVerticalStrut(5));card.add(pass);card.add(Box.createVerticalStrut(22));
        JButton login=button("SIGN IN",PINK,()->login(user.getText().trim(),new String(pass.getPassword())));login.setAlignmentX(Component.CENTER_ALIGNMENT);login.setMaximumSize(new Dimension(360,44));card.add(login);card.add(Box.createVerticalStrut(10));
        JButton register=button("CREATE ACCOUNT",PURPLE,()->register(user.getText().trim(),new String(pass.getPassword())));register.setAlignmentX(Component.CENTER_ALIGNMENT);register.setMaximumSize(new Dimension(360,44));card.add(register);card.add(Box.createVerticalStrut(18));
        JLabel demo=label("Demo admin: admin  /  admin123",12,MUTED);demo.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(demo);
        outer.add(card);frame.add(outer);frame.setVisible(true);
    }
    static void login(String u,String p){if(u.isEmpty()||p.isEmpty()){error("Enter username and password.");return;}try(Connection c=db();PreparedStatement q=c.prepareStatement("SELECT role FROM users WHERE username=? AND password=?")){q.setString(1,u);q.setString(2,p);try(ResultSet r=q.executeQuery()){if(r.next()){currentUser=u;admin="ADMIN".equals(r.getString(1));showHome();}else error("Login details not found. Create an account or try again.");}}catch(Exception e){error(e.getMessage());}}
    static void register(String u,String p){if(u.length()<3||p.length()<4){error("Use a username of 3+ characters and password of 4+ characters.");return;}try(Connection c=db();PreparedStatement q=c.prepareStatement("INSERT INTO users(username,password) VALUES(?,?)")){q.setString(1,u);q.setString(2,p);q.executeUpdate();info("Account created! You can now sign in.");}catch(Exception e){error("Could not create account. Username may already exist.");}}
    static void showHome(){base("CINEMAX | Movie Booking");JPanel root=new JPanel(new BorderLayout(0,0));root.setBackground(BG);root.add(header(),BorderLayout.NORTH);main=new JPanel(new BorderLayout());main.setBackground(BG);root.add(main,BorderLayout.CENTER);frame.setContentPane(root);showMovies();frame.setVisible(true);}
    static JPanel header(){JPanel h=new JPanel(new BorderLayout());h.setBackground(new Color(15,17,34));h.setBorder(new EmptyBorder(16,24,16,24));JPanel left=new JPanel(new FlowLayout(FlowLayout.LEFT,18,0));left.setOpaque(false);left.add(label("CINEMAX",26,PINK));left.add(label("MOVIES  •  SHOWTIMES  •  MEMORIES",11,CYAN));JPanel right=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));right.setOpaque(false);right.add(label("Hi, "+currentUser,13,TEXT));right.add(button("MOVIES",PURPLE,()->showMovies()));right.add(button("MY BOOKINGS",PANEL2,()->showBookings()));if(admin)right.add(button("ADMIN STUDIO",new Color(0,140,155),()->showAdmin()));right.add(button("LOG OUT",new Color(180,45,80),()->{frame.dispose();currentUser="guest";admin=false;showLogin();}));h.add(left,BorderLayout.WEST);h.add(right,BorderLayout.EAST);return h;}
    static List<Movie> movies(){List<Movie> out=new ArrayList<>();try(Connection c=db();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,title,language,genre,price,poster FROM movies ORDER BY title")){while(r.next())out.add(new Movie(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getDouble(5),r.getString(6)));}catch(Exception e){error(e.getMessage());}return out;}
    static void showMovies(){main.removeAll();JPanel wrap=new JPanel(new BorderLayout(0,16));wrap.setBackground(BG);wrap.setBorder(new EmptyBorder(22,26,22,26));JPanel title=new JPanel(new BorderLayout());title.setOpaque(false);JPanel texts=new JPanel();texts.setOpaque(false);texts.setLayout(new BoxLayout(texts,BoxLayout.Y_AXIS));texts.add(label("Now Showing",30,TEXT));texts.add(Box.createVerticalStrut(5));texts.add(label("Pick a story. Pick your seats. Make it a movie night.",14,MUTED));title.add(texts,BorderLayout.WEST);JTextField search=field("Search movies");search.setPreferredSize(new Dimension(220,42));title.add(search,BorderLayout.EAST);wrap.add(title,BorderLayout.NORTH);
        JPanel grid=new JPanel(new GridLayout(0,4,18,18));grid.setBackground(BG);for(Movie m:movies())grid.add(movieCard(m));JScrollPane sc=new JScrollPane(grid);sc.setBorder(null);sc.getViewport().setBackground(BG);sc.getVerticalScrollBar().setUnitIncrement(18);wrap.add(sc,BorderLayout.CENTER);
        search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){void update(){String q=search.getText().toLowerCase();grid.removeAll();for(Movie m:movies())if(m.title.toLowerCase().contains(q)||m.language.toLowerCase().contains(q)||m.genre.toLowerCase().contains(q))grid.add(movieCard(m));grid.revalidate();grid.repaint();}public void insertUpdate(javax.swing.event.DocumentEvent e){update();}public void removeUpdate(javax.swing.event.DocumentEvent e){update();}public void changedUpdate(javax.swing.event.DocumentEvent e){update();}});
        main.add(wrap);main.revalidate();main.repaint();}
    static JPanel movieCard(Movie m){JPanel card=new JPanel(new BorderLayout(0,8));card.setBackground(PANEL);card.setBorder(new CompoundBorder(new LineBorder(new Color(43,49,78)),new EmptyBorder(10,10,10,10)));JLabel poster=new JLabel();poster.setHorizontalAlignment(SwingConstants.CENTER);poster.setPreferredSize(new Dimension(190,205));try{Image im=ImageIO.read(new File(m.poster));poster.setIcon(new ImageIcon(im.getScaledInstance(190,205,Image.SCALE_SMOOTH)));}catch(Exception e){poster.setText("CINEMAX");poster.setForeground(PINK);poster.setOpaque(true);poster.setBackground(PANEL2);}JPanel details=new JPanel();details.setOpaque(false);details.setLayout(new BoxLayout(details,BoxLayout.Y_AXIS));details.add(label(m.title,18,TEXT));details.add(Box.createVerticalStrut(4));details.add(label(m.language+"  •  "+m.genre,11,MUTED));details.add(Box.createVerticalStrut(8));details.add(label("₹"+(int)m.price+" onwards",15,CYAN));JButton book=button("BOOK TICKETS",PINK,()->bookMovie(m));book.setAlignmentX(Component.LEFT_ALIGNMENT);details.add(Box.createVerticalStrut(8));details.add(book);card.add(poster,BorderLayout.NORTH);card.add(details,BorderLayout.CENTER);return card;}
    static void bookMovie(Movie m){JDialog d=new JDialog(frame,"Book "+m.title,true);d.getContentPane().setBackground(BG);JPanel p=new JPanel();p.setBackground(PANEL);p.setBorder(new EmptyBorder(20,22,20,22));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(label("BOOK YOUR MOVIE",22,PINK));p.add(Box.createVerticalStrut(12));p.add(label(m.title+"  •  ₹"+(int)m.price+" per seat",14,TEXT));p.add(Box.createVerticalStrut(12));p.add(label("SELECT SHOWTIME",12,MUTED));String[] times={"10:00 AM","1:30 PM","4:45 PM","8:15 PM"};JComboBox<String> time=new JComboBox<>(times);styleCombo(time);p.add(time);p.add(Box.createVerticalStrut(14));p.add(label("SELECT SEATS (tap to select)",12,MUTED));JPanel seats=new JPanel(new GridLayout(4,6,7,7));seats.setBackground(PANEL);List<JToggleButton> chosen=new ArrayList<>();for(int i=1;i<=24;i++){final int n=i;JToggleButton b=new JToggleButton("S"+i);b.setForeground(TEXT);b.setBackground(PANEL2);b.setOpaque(true);b.setFocusPainted(false);b.setBorder(new LineBorder(new Color(65,76,112)));b.addItemListener(e->{b.setBackground(b.isSelected()?PINK:PANEL2);b.setForeground(Color.WHITE);});seats.add(b);chosen.add(b);}p.add(seats);p.add(Box.createVerticalStrut(16));JButton confirm=button("CONFIRM BOOKING",GREEN,()->{List<String> ss=new ArrayList<>();for(JToggleButton b:chosen)if(b.isSelected())ss.add(b.getText());if(ss.isEmpty()){error("Choose at least one seat.");return;}String st=(String)time.getSelectedItem();double total=ss.size()*m.price;try(Connection c=db();PreparedStatement q=c.prepareStatement("INSERT INTO bookings(username,movie_id,movie_title,show_time,seats,total) VALUES(?,?,?,?,?,?)")){q.setString(1,currentUser);q.setInt(2,m.id);q.setString(3,m.title);q.setString(4,st);q.setString(5,String.join(", ",ss));q.setDouble(6,total);q.executeUpdate();d.dispose();info("Booking confirmed! Seats: "+String.join(", ",ss)+" | Total: ₹"+(int)total);}catch(Exception e){error(e.getMessage());}});p.add(confirm);d.add(p);d.pack();d.setSize(560,600);d.setLocationRelativeTo(frame);d.setVisible(true);}
    static void styleCombo(JComboBox<?> c){c.setBackground(PANEL2);c.setForeground(TEXT);c.setFont(new Font("Segoe UI",Font.PLAIN,14));c.setBorder(new LineBorder(new Color(68,76,115)));c.setMaximumSize(new Dimension(450,40));}
    static void showBookings(){main.removeAll();JPanel p=new JPanel(new BorderLayout(0,14));p.setBackground(BG);p.setBorder(new EmptyBorder(24,28,24,28));p.add(label("My Bookings",28,TEXT),BorderLayout.NORTH);String[] cols={"ID","MOVIE","SHOWTIME","SEATS","TOTAL","STATUS","ACTION"};JTable table=new JTable(modelBookings(false));styleTable(table);p.add(new JScrollPane(table),BorderLayout.CENTER);JButton cancel=button("CANCEL SELECTED BOOKING",new Color(185,45,83),()->{int row=table.getSelectedRow();if(row<0){error("Select a booking row first.");return;}int id=(int)table.getValueAt(row,0);try(Connection c=db();PreparedStatement q=c.prepareStatement("UPDATE bookings SET status='CANCELLED' WHERE id=? AND username=? AND status='BOOKED'")){q.setInt(1,id);q.setString(2,currentUser);if(q.executeUpdate()>0)info("Booking cancelled.");else info("That booking is already cancelled.");showBookings();}catch(Exception e){error(e.getMessage());}});p.add(cancel,BorderLayout.SOUTH);main.add(p);main.revalidate();main.repaint();}
    static javax.swing.table.DefaultTableModel modelBookings(boolean all){String[] cols={"ID","MOVIE","SHOWTIME","SEATS","TOTAL","STATUS"};javax.swing.table.DefaultTableModel model=new javax.swing.table.DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};String sql=all?"SELECT id,movie_title,show_time,seats,total,status FROM bookings ORDER BY id DESC":"SELECT id,movie_title,show_time,seats,total,status FROM bookings WHERE username=? ORDER BY id DESC";try(Connection c=db();PreparedStatement q=c.prepareStatement(sql)){if(!all)q.setString(1,currentUser);try(ResultSet r=q.executeQuery()){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),"₹"+(int)r.getDouble(5),r.getString(6)});}}catch(Exception e){error(e.getMessage());}return model;}
    static void styleTable(JTable t){t.setBackground(PANEL);t.setForeground(TEXT);t.setGridColor(new Color(52,58,88));t.setRowHeight(32);t.setFont(new Font("Segoe UI",Font.PLAIN,13));t.setSelectionBackground(PURPLE);t.setSelectionForeground(Color.WHITE);t.getTableHeader().setBackground(PANEL2);t.getTableHeader().setForeground(CYAN);t.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12));}
    static void showAdmin(){main.removeAll();JPanel p=new JPanel(new BorderLayout(0,16));p.setBackground(BG);p.setBorder(new EmptyBorder(24,28,24,28));p.add(label("Admin Studio",28,TEXT),BorderLayout.NORTH);JPanel body=new JPanel(new GridLayout(1,2,20,0));body.setBackground(BG);JPanel form=new JPanel();form.setBackground(PANEL);form.setBorder(new EmptyBorder(20,20,20,20));form.setLayout(new BoxLayout(form,BoxLayout.Y_AXIS));form.add(label("ADD A MOVIE",18,PINK));JTextField title=field("Movie title"),lang=field("Language"),genre=field("Genre"),price=field("Ticket price (₹)"),poster=field("Poster path, e.g. posters/movie.jpg");for(JTextField f:new JTextField[]{title,lang,genre,price,poster}){f.setMaximumSize(new Dimension(500,42));form.add(Box.createVerticalStrut(10));form.add(f);}form.add(Box.createVerticalStrut(14));form.add(button("ADD MOVIE",PURPLE,()->{try(Connection c=db();PreparedStatement q=c.prepareStatement("INSERT INTO movies(title,language,genre,price,poster) VALUES(?,?,?,?,?)")){q.setString(1,title.getText().trim());q.setString(2,lang.getText().trim());q.setString(3,genre.getText().trim());q.setDouble(4,Double.parseDouble(price.getText().trim()));q.setString(5,poster.getText().trim());if(title.getText().trim().isEmpty())throw new Exception("Enter a movie title.");q.executeUpdate();info("Movie added.");showAdmin();}catch(Exception e){error("Could not add movie: "+e.getMessage());}}));JPanel right=new JPanel(new BorderLayout(0,10));right.setBackground(PANEL);right.setBorder(new EmptyBorder(15,15,15,15));right.add(label("ALL BOOKINGS",17,CYAN),BorderLayout.NORTH);JTable table=new JTable(modelBookings(true));styleTable(table);right.add(new JScrollPane(table),BorderLayout.CENTER);body.add(form);body.add(right);p.add(body,BorderLayout.CENTER);main.add(p);main.revalidate();main.repaint();}
    static void error(String s){JOptionPane.showMessageDialog(frame,s,"CINEMAX",JOptionPane.ERROR_MESSAGE);}
    static void info(String s){JOptionPane.showMessageDialog(frame,s,"CINEMAX",JOptionPane.INFORMATION_MESSAGE);}
}
